question.answer:
package main

import "fmt"

func signpost(miles int) {
	fmt.Println(miles, "miles to go")
	if miles == 0 {
		fmt.Println("You have arrived")
	} else if miles < 10 {
		fmt.Println("Nearly there")
	} else {
		fmt.Println("Keep driving")
	}
}
